package pricing

import (
	"fmt"
	"strconv"
	"strings"
)

// ParseCents turns a decimal price written as text into whole cents.
func ParseCents(s string) (int, error) {
	parts := strings.SplitN(strings.TrimSpace(s), ".", 2)
	whole, err := strconv.Atoi(parts[0])
	if err != nil {
		return 0, fmt.Errorf("bad price %q", s)
	}
	cents := whole * 100
	if len(parts) == 2 {
		frac, err := strconv.Atoi(parts[1])
		if err != nil {
			return 0, fmt.Errorf("bad price %q", s)
		}
		cents += frac
	}
	return cents, nil
}

