package pricing

// Tier returns the discount percent that applies to a subtotal in cents:
// nothing below $50, 5% from $50, 10% from $100.
func Tier(subtotal int) int {
	switch {
	case subtotal > 10000:
		return 10
	case subtotal > 5000:
		return 5
	}
	return 0
}

// Apply returns the subtotal after its tier discount.
func Apply(subtotal int) int {
	return subtotal - subtotal*Tier(subtotal)/100
}

files.invoice.go:
package pricing

import "fmt"

// Line is one invoice line: a quantity and a unit price as written.
type Line struct {
	Qty   int
	Price string
}

// Total sums the lines, applies the tier discount and formats the result
// as "$<dollars>.<cents>".
func Total(lines []Line) (string, error) {
	sub := 0
	for _, l := range lines {
		c, err := ParseCents(l.Price)
		if err != nil {
			return "", err
		}
		sub += c * l.Qty
	}
	final := Apply(sub)
	return fmt.Sprintf("$%d.%02d", final/100, final%100), nil
}

