package pricing

import "testing"

func TestTotalSmallOrderHasNoDiscount(t *testing.T) {
	got, err := Total([]Line{{Qty: 2, Price: "3.00"}})
	if err != nil || got != "$6.00" {
		t.Fatalf("Total = %q, %v; want $6.00", got, err)
	}
}

func TestTotalAtFiftyDollarsGetsFivePercent(t *testing.T) {
	got, err := Total([]Line{{Qty: 4, Price: "12.5"}})
	if err != nil || got != "$47.50" {
		t.Fatalf("Total = %q, %v; want $47.50", got, err)
	}
}

func TestTotalAtHundredDollarsGetsTenPercent(t *testing.T) {
	got, err := Total([]Line{{Qty: 8, Price: "12.5"}})
	if err != nil || got != "$90.00" {
		t.Fatalf("Total = %q, %v; want $90.00", got, err)
	}
}

