func TestHiddenParseCents(t *testing.T) {
	for _, c := range []struct {
		in   string
		want int
	}{{"12.5", 1250}, {"12.50", 1250}, {"0.05", 5}, {"7", 700}, {" 3.4 ", 340}, {"0", 0}} {
		got, err := ParseCents(c.in)
		if err != nil || got != c.want {
			t.Errorf("ParseCents(%q) = %d, %v; want %d", c.in, got, err, c.want)
		}
	}
	if _, err := ParseCents("abc"); err == nil {
		t.Error("ParseCents(abc) must fail")
	}
}

func TestHiddenTierBoundaries(t *testing.T) {
	for _, c := range []struct{ in, want int }{{0, 0}, {4999, 0}, {5000, 5}, {9999, 5}, {10000, 10}, {25000, 10}} {
		if got := Tier(c.in); got != c.want {
			t.Errorf("Tier(%d) = %d, want %d", c.in, got, c.want)
		}
	}
	if got := Apply(5000); got != 4750 {
		t.Errorf("Apply(5000) = %d, want 4750", got)
	}
	if got := Apply(4999); got != 4999 {
		t.Errorf("Apply(4999) = %d, want 4999", got)
	}
}
